window.Public=(()=>{
 const {esc:e,icon,link,btn,card,heading,crumbs,empty,badge,field,textarea,select}=UI;
 function relationships(q){const years=MCQ.ids(q.job_years_ids).map(id=>MCQ.get('years',id)).filter(Boolean);if(!years.length)return '';return `<div class="mcq-answer-years" aria-label="Job years"><span>${years.length===1?'Job year':'Job years'}:</span><div class="chips">${years.map(x=>link('year/'+x.id,e(x.name),'chip')).join('')}</div></div>`}
 function relatedMcqs(q,limit=5){const score=x=>{let n=0;if(MCQ.ids(q.child_subcategory_ids).some(id=>MCQ.ids(x.child_subcategory_ids).includes(id)))n+=8;if(MCQ.ids(q.subcategory_ids).some(id=>MCQ.ids(x.subcategory_ids).includes(id)))n+=5;if(q.category_id===x.category_id)n+=3;if(MCQ.ids(q.paper_id).some(id=>MCQ.ids(x.paper_id).includes(id)))n+=3;if(MCQ.ids(q.job_ids).some(id=>MCQ.ids(x.job_ids).includes(id)))n+=3;if(MCQ.ids(q.job_years_ids).some(id=>MCQ.ids(x.job_years_ids).includes(id)))n+=4;return n};return MCQ.publicMcqs().filter(x=>x.id!==q.id).map(x=>({x,s:score(x)})).filter(r=>r.s>0).sort((a,b)=>b.s-a.s||a.x.id-b.x.id).slice(0,limit).map(r=>r.x)}
 function mcq(id){const q=MCQ.publicMcqs().find(x=>x.id===+id);if(!q)return notFound();const cat=MCQ.get('categories',q.category_id),related=relatedMcqs(q),years=MCQ.ids(q.job_years_ids).map(x=>MCQ.get('years',x)).filter(Boolean);return UI.layout(`<div class="container page">${crumbs([['MCQs','mcqs'],[q.question]])}<div class="two-col"><article>${questionCard(q,1)}<section class="card related-box"><div class="section-head"><div><p class="eyebrow">KEEP PRACTISING</p><h2>Related MCQs</h2></div></div>${related.length?related.map((x,i)=>mini(x,i)).join(''):empty('No close matches yet','Explore the broader category for more practice.')}</section></article><aside><div class="card"><p class="eyebrow">QUESTION DETAILS</p><h3>${e(cat?.name||'MCQ')}</h3><p class="small muted">Stable public MCQ detail page prepared for clean production URLs.</p>${cat?link('category/'+cat.id,'Browse '+e(cat.name),'link'):''}</div>${years.length?`<div class="card" style="margin-top:18px"><h3>Related past papers</h3><div class="chips">${years.slice(0,8).map(y=>link('year/'+y.id,e(y.name),'chip')).join('')}</div></div>`:''}</aside></div></div>`,'categories')}

 function questionCard(q,number=1,compact=false){const answer=App.answers[q.id],chosen=App.choices[q.id];const rows=MCQ.publicMcqs(),globalIndex=rows.findIndex(x=>x.id===q.id),next=globalIndex>=0&&globalIndex<rows.length-1?rows[globalIndex+1]:rows[0];return `<article class="card mcq-card ${compact?'mcq-card-compact':''}" data-question="${q.id}" data-number="${number}"><div class="mcq-top"><div><span class="eyebrow">QUESTION ${String(number).padStart(2,'0')}</span> ${q.important?badge('important'):''}</div><div class="mcq-top-actions">${btn(icon('bookmark'),'bookmark','ghost',`data-id="${q.id}" aria-label="${MCQ.db.bookmarks.includes(q.id)?'Remove bookmark':'Bookmark question'}" aria-pressed="${MCQ.db.bookmarks.includes(q.id)}"`)}${compact&&next?link('practice/'+next.id,icon('arrow'),'btn ghost quick-next'):''}</div></div><h2>${e(q.question)}</h2><div class="options" role="group" aria-label="Answer options">${[1,2,3,4].map((n,i)=>{const text=q['option'+n];const state=answer?(text===q.correct_answer?'correct':text===chosen?'wrong':''):text===chosen?'selected':'';return btn(`<span class="letter">${'ABCD'[i]}</span><span>${e(text)}</span>`,'choose',`option ${state}`,`data-id="${q.id}" data-option="${n}" aria-pressed="${text===chosen}" ${answer?'disabled':''}`)}).join('')}</div>${answer?`<div class="explanation" role="status"><strong>Correct answer: ${e(q.correct_answer)}</strong><p>${e(q.description||'No explanation has been added yet.')}</p>${relationships(q)}</div>`:''}<div class="actions">${!answer?'<span class="small muted">Select an option to check your answer instantly.</span>':''}<span class="spacer"></span>${btn(icon('share'),'share','ghost',`data-id="${q.id}" aria-label="Share question"`)}${btn(icon('copy'),'copy','ghost',`data-id="${q.id}" aria-label="Copy question link"`)}${btn(icon('flag'),'report','ghost',`data-id="${q.id}" aria-label="Report question"`)}</div></article>`}
 function mini(q,index){return `<div class="card question-row"><span class="number">${String(index+1).padStart(2,'0')}</span><div class="grow">${link('practice/'+q.id,`<h3>${e(q.question)}</h3>`)}<span class="small muted">${e(MCQ.get('categories',q.category_id)?.name)} · 4 options</span></div>${link('practice/'+q.id,icon('arrow'),'btn ghost')}</div>`}
 function quickCard(){const quick=MCQ.topMcqs(),qi=Math.max(0,Math.min(Number(App.homeQuickIndex||0),Math.max(0,quick.length-1))),q=quick[qi];return q?`<div class="hero-quick"><div class="quick-head"><div><span class="eyebrow">FEATURED MCQ</span><strong>${String(qi+1).padStart(2,'0')} / ${String(quick.length).padStart(2,'0')}</strong></div>${btn('›','home-quick-next','quick-next-control',`aria-label="Next quick MCQ"`)}</div><h3>${e(q.question)}</h3><div class="quick-options">${[1,2,3,4].map((n,i)=>{const text=q['option'+n],chosen=App.quickAnswer?.id===q.id?App.quickAnswer.choice:null,answered=App.quickAnswer?.id===q.id,state=answered?(text===q.correct_answer?'correct':text===chosen?'wrong':''):text===chosen?'selected':'';return btn(`<span class="letter">${'ABCD'[i]}</span><span>${e(text)}</span>`,'home-quick-choose',`quick-option ${state}`,`data-id="${q.id}" data-option="${n}" ${answered?'disabled':''}`)}).join('')}</div>${App.quickAnswer?.id===q.id?`<div class="quick-answer">Correct answer: <strong>${e(q.correct_answer)}</strong><p>${e(q.description||'No explanation has been added yet.')}</p>${relationships(q)}</div>`:''}<div class="quick-dots">${quick.map((_,i)=>`<button type="button" class="quick-dot ${i===qi?'active':''}" data-action="home-quick-jump" data-index="${i}" aria-label="Quick MCQ ${i+1}"></button>`).join('')}</div></div>`:'';}
 function home(){const qs=MCQ.publicMcqs();const signature=qs.map(q=>q.id).sort((a,b)=>a-b).join(',');if(App.homeRandomSignature!==signature||App.homeRandomIds.length!==qs.length){const ids=qs.map(q=>q.id);for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}App.homeRandomIds=ids;App.homeRandomSignature=signature}const randomQs=App.homeRandomIds.map(id=>qs.find(q=>q.id===id)).filter(Boolean),homePageSize=10,homePage=App.page(randomQs.length,homePageSize),homeRows=randomQs.slice((homePage-1)*homePageSize,homePage*homePageSize);const cats=MCQ.db.categories.filter(c=>c.active!==false&&!c.legacy).slice(0,6);const catIcon=c=>{const raw=String(c.icon||'').trim();const emoji=raw&&!/^[a-z0-9 _-]+$/i.test(raw);return `<span class="home-cat-icon">${emoji?e(raw):icon(raw||'grid')}</span>`};const catNav=cats.map(c=>`<div class="home-cat-group"><div class="home-cat-title">${link('category/'+c.id,`${catIcon(c)}<span>${e(c.name)}</span>${icon('arrow')}`)}</div><div class="home-sub-list">${MCQ.db.subcategories.filter(s=>s.category_id===c.id&&s.active!==false).slice(0,4).map(x=>link('subcategory/'+x.id,e(x.name),'home-sub-link')).join('')}</div></div>`).join('');const stats=[[qs.length,'Practice MCQs','book'],[MCQ.db.years.filter(x=>x.active!==false).length,'Past papers','paper'],[MCQ.db.jobs.filter(x=>x.active!==false).length,'Jobs','briefcase'],[MCQ.categoryCounts(true).categories,'Main categories','grid']];const quickPanel=quickCard();return UI.layout(`<div class="container"><section class="hero"><div class="hero-grid"><div><p class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</p><h1>A little practice.<br>A lot of <em>progress.</em></h1><p class="hero-copy">Find your subject. Explore past papers. Turn what you know into the confidence you need.</p><form data-form="search">${UI.search('What would you like to practise?')}</form></div>${quickPanel}</div><div class="stats-row home-stats">${stats.map(([n,l,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${UI.counter(n)}</strong><span>${l}</span></div></div>`).join('')}</div></section><section class="section home-content-grid"><div><div class="section-head"><div><p class="eyebrow">ALL PRACTICE</p><h2>Random MCQs from the full collection</h2></div>${link('mcqs','View all','link')}</div><p class="small muted">Showing ${homeRows.length} of ${randomQs.length} approved MCQs · 10 per page</p><div class="home-mcq-list">${homeRows.map((q,i)=>questionCard(q,(homePage-1)*homePageSize+i+1,true)).join('')}</div>${UI.pager(randomQs.length,homePage,homePageSize,App.route.params,'home')}</div><aside class="home-category-nav card"><div class="section-head"><div><p class="eyebrow">EXPLORE</p><h2>Categories</h2></div></div><div class="home-cat-boxes">${catNav}</div>${link('categories','View All Categories '+icon('arrow'),'btn home-cat-more','')}</aside></section><section class="section"><div class="section-head"><div><p class="eyebrow">PREPARE WITH PURPOSE</p><h2>Explore popular papers</h2></div>${link('papers','All organizations '+icon('arrow'),'link')}</div><div class="grid paper-grid">${[32,26,27].map((id,i)=>MCQ.get('papers',id)?card('papers',MCQ.get('papers',id),i):'').join('')}</div></section><section class="section discovery-section"><div class="section-head"><div><p class="eyebrow">DISCOVER MORE</p><h2>Fresh ways to practise</h2></div></div><div class="discovery-grid"><div class="card"><h3>Latest past papers</h3>${MCQ.db.years.filter(x=>x.active!==false).slice(-4).reverse().map(x=>link('year/'+x.id,e(x.name),'discovery-link')).join('')}</div><div class="card"><h3>Latest guides</h3>${MCQ.db.guides.slice(-4).reverse().map(x=>link('guide/'+x.id,e(x.name),'discovery-link')).join('')}</div><div class="card"><h3>Latest posts</h3>${(MCQ.db.posts||[]).filter(x=>x.published!==false).slice(0,4).map(x=>link('post/'+x.id,e(x.title),'discovery-link')).join('')||'<span class="small muted">No published posts yet.</span>'}</div><div class="card"><h3>Explore by organization</h3>${MCQ.db.papers.filter(x=>x.active!==false).slice(0,6).map(x=>link('paper/'+x.id,e(x.name),'chip')).join('')}</div></div></section><section class="cta"><div><p class="eyebrow">SMALL STEPS ADD UP</p><h2>Make this your learning space.</h2><p>Practice by topic, track your progress, and return to saved papers.</p></div>${link('dashboard','My learning dashboard '+icon('arrow'),'btn primary')}</section></div>`,'home')}
 function browse(type,id){const map={categories:['categories','All subjects','Choose a subject, then narrow your focus.'],category:['subcategories','Subjects','Select a subject to explore its topics.'],subcategory:['children','Topics','Choose a topic to start practising.'],papers:['papers','Past papers','Browse organizations, jobs, and dated paper records.'],paper:['jobs','Jobs','Select a job to see its past papers.'],job:['years','Past papers','Choose a paper to explore available practice questions.'],jobs:['jobs','Jobs','Browse job and recruitment preparation records available on MCQ Campus.']};const [collection,title,desc]=map[type];let rows=MCQ.db[collection].filter(x=>x.active!==false),trail=[],name=title;let parent;if(id){const parentType={category:'categories',subcategory:'subcategories',paper:'papers',job:'jobs'}[type];parent=MCQ.get(parentType,id);if(!parent)return notFound();name=parent.name;const rel=MCQ.parents[collection];rows=rows.filter(x=>x[rel[1]]===+id);if(type==='category')trail=[['Categories','categories']];if(type==='subcategory'){const ca=MCQ.get('categories',parent.category_id);trail=[['Categories','categories'],[ca.name,'category/'+ca.id]]}if(type==='paper')trail=[['Past papers','papers']];if(type==='job'){const pa=MCQ.get('papers',parent.paper_id);trail=[['Past papers','papers'],[pa.name,'paper/'+pa.id]]}}
 const params=App.route.params,q=params.q||'',sort=params.sort||'name',available=params.available==='1';rows=rows.filter(x=>MCQ.norm(x.name).includes(MCQ.norm(q)));if(available)rows=rows.filter(x=>collection==='years'?MCQ.publicMcqs().some(q=>q.job_years_ids.includes(x.id)):collection==='children'?MCQ.publicMcqs().some(q=>q.child_subcategory_ids.includes(x.id)):true);rows=[...rows].sort((a,b)=>sort==='new'?b.id-a.id:a.name.localeCompare(b.name));const page=App.page(rows.length);return UI.layout(`<div class="container page">${crumbs([...trail,[name]])}${heading(name,desc)}<form class="toolbar" data-form="filter">${UI.search('Search '+title.toLowerCase(),q)}<select name="sort" aria-label="Sort results"><option value="name">Name A–Z</option><option value="new" ${sort==='new'?'selected':''}>Newest record</option></select>${['years','children'].includes(collection)?`<label class="check-line"><input type="checkbox" name="available" value="1" ${available?'checked':''}>Has demo MCQs</label>`:''}</form><p class="small muted">${rows.length} ${collection==='years'?'paper records':collection} · ${['papers','jobs','years'].includes(collection)?'Reference records; full question collections are not included.':'2026 category file'}</p>${rows.length?`<div class="grid ${['papers','jobs','years'].includes(collection)?'paper-grid':''}">${rows.slice((page-1)*12,page*12).map((x,i)=>card(collection,x,i)).join('')}</div>${UI.pager(rows.length,page,12,params)}`:empty('No matches here','Try a different search, or clear the available MCQs filter.',link(App.route.path,'Clear filters','btn'))}</div>`,['papers','paper','job'].includes(type)?'papers':'categories')}
 function listing(type,id){let rows=MCQ.publicMcqs(),title='Practice MCQs',desc='Choose a question and check your understanding.',trail=[['MCQs']],record;const p=App.route.params;let listHeader='';if(type==='topic'){record=MCQ.get('children',id);if(!record)return notFound();const su=MCQ.get('subcategories',record.subcategory_id),ca=MCQ.get('categories',su.category_id);title=record.name;rows=rows.filter(q=>q.child_subcategory_ids.includes(+id));trail=[['Categories','categories'],[ca.name,'category/'+ca.id],[su.name,'subcategory/'+su.id],[title]]}if(type==='year'){record=MCQ.get('years',id);if(!record)return notFound();const j=MCQ.get('jobs',record.job_id),pa=MCQ.get('papers',j.paper_id);title=record.name;rows=rows.filter(q=>q.job_years_ids.includes(+id));trail=[['Papers','papers'],[pa.name,'paper/'+pa.id],[j.name,'job/'+j.id],[title]];listHeader=`<div class="notice">This is a reference paper record. Attached practice questions are illustrative demo associations.</div>${btn(icon('bookmark')+' '+(MCQ.db.savedPapers.includes(+id)?'Remove saved paper':'Save paper'),'save-paper','',`data-id="${id}"`)}`}
 if(type==='important'){title='Worth another look';desc='A selected collection of important practice concepts.';rows=rows.filter(q=>q.important);trail=[['Important MCQs']]}
 if(type==='search'){title=p.q?'Results for “'+p.q+'”':'What would you like to practise?';desc='Search questions and discover related subjects or paper records.';trail=[['Search']]}
 if(p.category)rows=rows.filter(q=>q.category_id===+p.category);if(p.q)rows=rows.filter(q=>MCQ.norm(q.question+' '+[1,2,3,4].map(i=>q['option'+i]).join(' ')).includes(MCQ.norm(p.q)));if(p.sort==='new')rows.sort((a,b)=>b.id-a.id);const pageSize=10;const page=App.page(rows.length,pageSize);const related=type==='search'&&p.q?['categories','papers','jobs'].flatMap(t=>MCQ.list(t,p.q).slice(0,3).map(x=>({t,x}))):[];const searchPosts=type==='search'&&p.q?(MCQ.db.posts||[]).filter(x=>x.published!==false&&MCQ.norm((x.title||'')+' '+(x.excerpt||'')).includes(MCQ.norm(p.q))).slice(0,3):[];const searchGuides=type==='search'&&p.q?(MCQ.db.guides||[]).filter(x=>MCQ.norm((x.name||'')+' '+(x.summary||'')).includes(MCQ.norm(p.q))).slice(0,3):[];return UI.layout(`<div class="container page">${crumbs(trail)}${heading(title,desc)}${listHeader}<form class="toolbar" data-form="filter">${UI.search('Search questions',p.q||'')}<select name="category" aria-label="Filter category"><option value="">All categories</option>${MCQ.db.categories.map(c=>`<option value="${c.id}" ${+p.category===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select><select name="sort" aria-label="Sort questions"><option value="">Default order</option><option value="new" ${p.sort==='new'?'selected':''}>Newest first</option></select></form>${type==='search'&&p.q?`<div class="search-groups">${related.length?`<section><div class="section-head"><h3>Categories, papers & jobs</h3></div><div class="grid section">${related.map(({t,x},i)=>card(t,x,i)).join('')}</div></section>`:''}${searchPosts.length?`<section><div class="section-head"><h3>Posts</h3></div><div class="post-grid">${searchPosts.map(x=>link('post/'+x.id,`<h3>${e(x.title)}</h3><p>${e(x.excerpt||'Read post')}</p>`,'card clickable')).join('')}</div></section>`:''}${searchGuides.length?`<section><div class="section-head"><h3>Guides</h3></div><div class="grid">${searchGuides.map(x=>link('guide/'+x.id,`<h3>${e(x.name)}</h3><p>${e(x.summary||'Read guide')}</p>`,'card clickable')).join('')}</div></section>`:''}</div>`:''}<div class="two-col"><div>${rows.length?`<p class="small muted">${rows.length} available practice questions</p><div class="question-list">${rows.slice((page-1)*pageSize,page*pageSize).map((q,i)=>questionCard(q,(page-1)*pageSize+i+1,true)).join('')}</div>${UI.pager(rows.length,page,pageSize,p)}`:empty('No questions available','Try another topic or explore the complete demo collection.',link('mcqs','Explore practice MCQs','btn primary'))}</div><aside><div class="card"><span class="tile-icon">${icon('book')}</span><h3>Study with a little structure</h3><p>Answer first, read the explanation, then save anything you want to revisit.</p><div class="card-foot">${link('dashboard','Open my learning','link')}</div></div></aside></div></div>`,type==='important'?'important':type==='year'?'papers':'categories')}
 function practice(id){const q=MCQ.publicMcqs().find(x=>x.id===+id);if(!q)return notFound();MCQ.recent(id);const rows=MCQ.publicMcqs(),i=rows.indexOf(q);const cat=MCQ.get('categories',q.category_id);return UI.layout(`<div class="container page">${crumbs([['Practice','mcqs'],['Question '+id]])}<div class="two-col"><div>${questionCard(q,i+1)}<div class="actions">${i?link('practice/'+rows[i-1].id,'← Previous','btn'):''}<span class="spacer"></span><span class="small muted">${i+1} of ${rows.length}</span><span class="spacer"></span>${i<rows.length-1?link('practice/'+rows[i+1].id,'Next question '+icon('arrow'),'btn primary'):link('dashboard','View progress','btn primary')}</div></div><aside><div class="card"><p class="eyebrow">YOUR PRACTICE SPACE</p><h3>${e(cat?.name)}</h3><p>Take your time. Focus on why an answer is correct.</p><div class="card-foot">${link('category/'+q.category_id,'Explore this subject','link')}</div></div><div class="card" style="margin-top:20px"><h3>Session progress</h3><p>${MCQ.db.attempts.length} answers checked</p><div style="margin:18px 0" class="progress-track"><span style="width:${Math.min(100,new Set(MCQ.db.attempts.map(a=>a.id)).size/rows.length*100)}%"></span></div>${link('dashboard','View my learning '+icon('arrow'),'link')}</div></aside></div></div>`)}
 function guides(id){const g=MCQ.get('guides',id);if(id&&!g)return notFound();return UI.layout(`<div class="container page">${crumbs(id?[['Guides','guides'],[g.name]]:[['Guides']])}${id?`<article class="article"><p class="eyebrow">${e(g.tag)}</p><h1>${e(g.name)}</h1><p>${e(g.summary)}</p>${g.body.split(/\n\n/).map(t=>`<p>${e(t)}</p>`).join('')}<hr style="border:0;border-top:1px solid var(--line);margin:30px 0">${link('mcqs','Put it into practice '+icon('arrow'),'btn primary')}</article>`:`${heading('Build your study rhythm','Simple guides to make your practice more useful.')}<div class="grid">${MCQ.db.guides.map((x,i)=>link('guide/'+x.id,`<span class="tile-icon tint-${i}">${icon('book')}</span><p class="eyebrow" style="margin-top:25px">${e(x.tag)}</p><h3>${e(x.name)}</h3><p>${e(x.summary)}</p><div class="card-foot"><span>Read guide</span>${icon('arrow')}</div>`,'card clickable')).join('')}</div>`}</div>`,'guides')}
 function posts(id){const safeUrl=u=>/^(https?:\/\/|#\/)/i.test(String(u||''));const all=(MCQ.db.posts||[]).filter(x=>x.published!==false);if(id){const post=all.find(x=>+x.id===+id);if(!post)return notFound();const links=(post.links||[]).filter(x=>safeUrl(x.url));return UI.layout(`<div class="container page">${crumbs([['Posts','posts'],[post.title]])}<article class="article post-article"><p class="eyebrow">MCQ CAMPUS POST</p><h1>${e(post.title)}</h1>${post.excerpt?`<p class="post-lead">${e(post.excerpt)}</p>`:''}${String(post.body||'').split(/\n\n+/).filter(Boolean).map(t=>`<p>${e(t)}</p>`).join('')}${links.length?`<div class="post-links"><h3>Useful links</h3>${links.map(x=>`<a class="btn" href="${e(x.url)}" ${/^https?:/i.test(x.url)?'target="_blank" rel="noopener"':''}>${e(x.label||x.url)} ${icon('arrow')}</a>`).join('')}</div>`:''}<div class="post-practice-cta">${link('mcqs','Practice MCQs '+icon('arrow'),'btn primary')} ${link('important','Important MCQs','btn')}</div></article></div>`,'posts')}
 const p=App.route.params;let rows=[...all].sort((a,b)=>String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||'')));if(p.q)rows=rows.filter(x=>MCQ.norm((x.title||'')+' '+(x.excerpt||'')+' '+(x.body||'')).includes(MCQ.norm(p.q)));const pageSize=10,page=App.page(rows.length,pageSize);return UI.layout(`<div class="container page">${crumbs([['Posts']])}${heading('Posts & learning resources','Helpful notes, updates and links that connect reading with MCQ practice.')}<form class="toolbar" data-form="filter">${UI.search('Search posts',p.q||'')}</form>${rows.length?`<div class="post-grid">${rows.slice((page-1)*pageSize,page*pageSize).map(post=>`<article class="card post-card"><p class="eyebrow">POST</p><h2>${e(post.title)}</h2>${post.excerpt?`<p>${e(post.excerpt)}</p>`:''}<div class="card-foot"><span class="small muted">${UI.date(post.updated_at||post.created_at)}</span>${link('post/'+post.id,'Read post '+icon('arrow'),'link')}</div></article>`).join('')}</div>${UI.pager(rows.length,page,pageSize,p,'posts')}`:empty('No posts published yet','Published posts will appear here.')}</div>`,'posts')}
 function auth(type){const titles={login:'Welcome back',register:'Your next chapter',forgot:'Forgot your password?',reset:'Choose a new password',verify:'Check your email'};let form='';if(type==='login')form=`<p class="muted small">Enter an existing demo account email. The account's assigned roles determine which workspace opens. This frontend does not verify passwords.</p><form data-form="auth-login">${field('email','Email address','','email',true,'autocomplete="email"')}${field('password','Password','','password',true,'autocomplete="current-password"')}<div class="actions" style="margin-bottom:20px"><label class="check-line"><input type="checkbox" name="remember"> Remember me</label><span class="spacer"></span>${link('forgot','Forgot password?','link')}</div><button class="btn primary">Sign in</button></form><p class="text-center small" style="margin-top:18px">New here? ${link('register','Create an account','link')}</p><div class="notice" style="margin-top:22px"><strong>Demo accounts</strong><p>Learner: learner@example.com<br>Admin + Learner: editor@example.com<br>Super Admin + Learner: owner@example.com</p></div>`;
 if(type==='register')form=`<p class="small muted">Registration preview. Details are not sent to a server.</p><form data-form="auth-register">${field('name','Full name','','text',true)}${field('email','Email address','','email',true)}${field('password','Password','','password',true,'minlength="8" autocomplete="new-password"')}${field('confirm','Confirm password','','password',true,'minlength="8" autocomplete="new-password"')}${select('country','Country',[{id:'Pakistan',name:'Pakistan'},{id:'Other',name:'Other'}],'Pakistan',true)}${field('whatsapp','WhatsApp number','','tel',true,'placeholder="e.g. +92 300 1234567" autocomplete="tel"')}<label class="check-line"><input type="checkbox" required> I accept the ${link('terms','terms','link')}</label><button class="btn primary">Preview registration</button></form><p class="text-center small" style="margin-top:18px">Already registered? ${link('login','Log in','link')}</p>`;
 if(type==='forgot')form=`<p class="muted">Enter an email to preview the reset-request state.</p><form data-form="auth-forgot">${field('email','Email address','','email',true)}<button class="btn primary">Preview reset request</button></form><p class="small" style="margin-top:20px">${link('reset','View reset password form','link')}</p>`;
 if(type==='reset')form=`<div class="notice warning">Demo reset form. No reset token is issued and no password will be changed.</div><form data-form="auth-reset">${field('password','New password','','password',true,'minlength="8" autocomplete="new-password"')}${field('confirm','Confirm new password','','password',true,'minlength="8" autocomplete="new-password"')}<button class="btn primary">Preview reset</button></form>`;
 if(type==='verify')form=`<div class="tile-icon">${icon('check')}</div><h3 style="margin-top:20px">Verification screen preview</h3><p class="muted">In the connected app, an email verification link will arrive in your inbox. This demo has not sent an email or created an account.</p>${btn('Preview resend','resend','primary')}<p style="margin-top:18px">${link('login','Return to login','link')}</p>`;
 return UI.layout(`<div class="container"><div class="auth-layout"><div class="auth-story"><p class="eyebrow">MCQ CAMPUS</p><h2>Make room<br>for progress.</h2><p>Your questions, your pace,<br>your next step forward.</p></div><div class="auth-form"><h1>${titles[type]}</h1>${form}</div></div></div>`)}
 function dashboard(view='overview'){
  const d=MCQ.db,s=d.session;
  const allowedViews=['overview','practice','important','mistakes','saved','papers','jobs','performance','history','notifications','profile','settings'];
  if(!allowedViews.includes(view))view='overview';
  const attempts=d.attempts||[],publicMcqs=MCQ.publicMcqs(),correct=attempts.filter(x=>x.correct).length,wrong=attempts.length-correct,accuracy=attempts.length?Math.round(correct/attempts.length*100):0;
  const uniqueAttempts=[...new Set(attempts.map(a=>+a.id))],attemptedSet=new Set(uniqueAttempts);
  const savedMcqs=(d.bookmarks||[]).map(id=>MCQ.get('mcqs',id)).filter(Boolean);
  const mistakes=[];for(const a of attempts){if(a.correct||mistakes.some(x=>x.id===+a.id))continue;const q=MCQ.get('mcqs',a.id);if(q)mistakes.push(q)}
  const categoryStats=d.categories.map(cat=>{const rows=attempts.filter(a=>MCQ.get('mcqs',a.id)?.category_id===cat.id),ok=rows.filter(a=>a.correct).length;return {cat,total:rows.length,correct:ok,wrong:rows.length-ok,accuracy:rows.length?Math.round(ok/rows.length*100):0}}).filter(x=>x.total);
  const weak=categoryStats.filter(x=>x.total>=3).sort((a,b)=>a.accuracy-b.accuracy||b.total-a.total).slice(0,4);
  const recentAttempt=attempts[0],recentQ=recentAttempt&&MCQ.get('mcqs',recentAttempt.id);
  const relatedJobIds=[];for(const a of attempts){const q=MCQ.get('mcqs',a.id);for(const id of MCQ.ids(q?.job_ids))if(!relatedJobIds.includes(id))relatedJobIds.push(id)}
  const jobRows=relatedJobIds.map(id=>MCQ.get('jobs',id)).filter(Boolean);
  const avatar=s?.avatar?`<img class="profile-photo" src="${e(s.avatar)}" alt="">`:`<span class="avatar">${e((s?.name||'Learner').split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;
  const nav=[
   ['overview','Dashboard','grid'],['practice','Practice MCQs','book'],['important','Important MCQs','flag'],['mistakes','My Mistakes','flag'],['saved','Saved MCQs','bookmark'],['papers','Past Papers','paper'],
   ['jobs','My Job Preparation','briefcase'],['performance','My Performance','grid'],['history','Practice History','history'],['notifications','Notifications','bell'],['profile','Profile','user'],['settings','Settings','settings']
  ];
  const side=`<aside class="learner-side card" id="learner-sidebar"><div class="learner-side-head"><strong>My Learning</strong><span class="small muted">Personal preparation center</span></div><nav>${nav.map(([id,label,ic])=>link('dashboard/'+id,`${icon(ic)}<span>${label}</span>`,view===id?'active':'' )).join('')}</nav></aside>`;
  const summary=`<div class="learner-metrics"><div class="card metric"><span>MCQs Attempted</span><strong>${attempts.length}</strong></div><div class="card metric"><span>Correct</span><strong>${correct}</strong></div><div class="card metric"><span>Wrong</span><strong>${wrong}</strong></div><div class="card metric"><span>Accuracy</span><strong>${accuracy}%</strong></div><div class="card metric"><span>Saved MCQs</span><strong>${savedMcqs.length}</strong></div><div class="card metric"><span>Saved Papers</span><strong>${(d.savedPapers||[]).length}</strong></div></div>`;
  const quick=`<div class="learner-quick-actions">${link('mcqs','Practice MCQs','btn primary')}${link('papers','Attempt Past Paper','btn')}${link('dashboard/jobs','Job Preparation','btn')}${link('dashboard/mistakes','Review Mistakes','btn')}</div>`;
  let body='';
  if(view==='overview'){
   const recentActivities=attempts.slice(0,5).map(a=>{const q=MCQ.get('mcqs',a.id),cat=MCQ.get('categories',q?.category_id);return `<div class="learner-activity-row"><span class="status-dot ${a.correct?'ok':'bad'}"></span><div><strong>${e(q?.question||'MCQ attempt')}</strong><span>${e(cat?.name||'Practice')} · ${a.correct?'Correct':'Incorrect'} · ${UI.date(a.at)}</span></div></div>`}).join('');
   body=`${summary}<section class="card learner-continue"><div><p class="eyebrow">CONTINUE PREPARATION</p><h2>${recentQ?e(recentQ.question):'Start your first preparation session.'}</h2><p class="small muted">${recentQ?'Return to your most recently attempted question and keep practising.':'Choose any category or past paper to begin tracking your progress.'}</p></div>${recentQ?link('practice/'+recentQ.id,'Continue Preparation '+icon('arrow'),'btn primary'):link('mcqs','Start practising '+icon('arrow'),'btn primary')}</section>${quick}<div class="learner-home-grid"><section class="card"><div class="section-head"><div><p class="eyebrow">WEEKLY / OVERALL PROGRESS</p><h2>Category progress</h2></div>${link('dashboard/performance','Full performance','link')}</div>${categoryStats.slice(0,6).map(x=>`<div class="bar-row"><div class="row"><span>${e(x.cat.name)}</span><span>${x.correct} / ${x.total} · ${x.accuracy}%</span></div><div class="progress-track"><span style="width:${x.accuracy}%"></span></div></div>`).join('')||empty('No activity yet','Your subject progress appears after you answer MCQs.')}</section><section class="card"><div class="section-head"><div><p class="eyebrow">WEAK AREAS</p><h2>Needs more practice</h2></div></div>${weak.length?weak.map(x=>`<div class="weak-row"><span>${e(x.cat.name)}</span><strong>${x.accuracy}%</strong></div>`).join('')+link('dashboard/mistakes','Practice weak areas','btn sm'):empty('No weak areas yet','Answer at least 3 questions in a category before it is evaluated.')}</section><section class="card"><div class="section-head"><div><p class="eyebrow">JOB PREPARATION</p><h2>Based on your activity</h2></div></div>${jobRows.length?jobRows.slice(0,5).map(j=>`<div class="learner-list-row">${link('job/'+j.id,e(j.name),'link')}</div>`).join(''):empty('No job preparation yet','Practice job-linked MCQs to build this section.')}</section><section class="card"><div class="section-head"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>Latest practice</h2></div>${link('dashboard/history','View history','link')}</div>${recentActivities||empty('No recent activity','Your preparation history will appear here.')}</section></div>`;
  }
  if(view==='practice'){
   const unattempted=publicMcqs.filter(q=>!attemptedSet.has(q.id)).slice(0,20);
   body=`${heading('Practice MCQs','Choose where to continue your preparation.')}${quick}<div class="card"><h2>Unattempted MCQs</h2>${unattempted.length?unattempted.map((q,i)=>mini(q,i)).join(''):empty('You have explored every available MCQ','Revisit your mistakes or try random practice.')}</div>`;
  }
  if(view==='important'){const rows=publicMcqs.filter(q=>q.important);body=`${heading('Important MCQs','High-priority questions selected by the content team.')}${rows.length?rows.slice(0,30).map((q,i)=>mini(q,i)).join(''):empty('No important MCQs available','Check again when important questions are published.')}`}
  if(view==='mistakes')body=`${heading('My Mistakes','Questions you answered incorrectly. Retry them until they become strengths.')}${mistakes.length?mistakes.map((q,i)=>mini(q,i)).join(''):empty('No mistakes to review','Incorrect answers will appear here automatically.',link('mcqs','Practice MCQs','btn primary'))}`;
  if(view==='saved')body=`${heading('Saved MCQs','Your bookmarked revision list.')}${savedMcqs.length?savedMcqs.map((q,i)=>mini(q,i)).join(''):empty('No saved MCQs yet','Bookmark questions while practising to keep them here.',link('mcqs','Browse MCQs','btn primary'))}`;
  if(view==='papers'){const rows=(d.savedPapers||[]).map(id=>MCQ.get('papers',id)||MCQ.get('years',id)).filter(Boolean);body=`${heading('Past Papers','Saved papers and paper-based preparation.')}${rows.length?`<div class="grid paper-grid">${rows.map((x,i)=>card(MCQ.get('papers',x.id)?'papers':'years',x,i)).join('')}</div>`:empty('No saved papers yet','Browse past papers and save the ones you want to revisit.',link('papers','Explore papers','btn primary'))}`}
  if(view==='jobs'){const rows=jobRows.length?jobRows:d.jobs.filter(x=>x.active!==false).slice(0,20);body=`${heading('My Job Preparation','Job-linked preparation from your real MCQ activity. Job deadlines are not shown because the current Job model does not store posting/deadline data.')}${rows.length?`<div class="grid paper-grid">${rows.map((x,i)=>card('jobs',x,i)).join('')}</div>`:empty('No job preparation yet','Start practising MCQs linked to a job.')}`}
  if(view==='performance'){
   body=`${heading('My Performance','Learner-specific analytics from your actual attempts.')}${summary}<div class="card"><h2>Category performance</h2>${categoryStats.length?`<div class="table-wrap"><table><thead><tr><th>Category</th><th>Attempted</th><th>Correct</th><th>Wrong</th><th>Accuracy</th></tr></thead><tbody>${categoryStats.map(x=>`<tr><td>${e(x.cat.name)}</td><td>${x.total}</td><td>${x.correct}</td><td>${x.wrong}</td><td>${x.accuracy}%</td></tr>`).join('')}</tbody></table></div>`:empty('No performance data yet','Answer MCQs to build your performance report.')}</div>`;
  }
  if(view==='history'){
   body=`${heading('Practice History','Your latest MCQ attempts, newest first.')}${attempts.length?`<div class="card table-wrap"><table><thead><tr><th>Date</th><th>Question</th><th>Category</th><th>Result</th><th>Action</th></tr></thead><tbody>${attempts.slice(0,100).map(a=>{const q=MCQ.get('mcqs',a.id),cat=MCQ.get('categories',q?.category_id);return `<tr><td>${UI.date(a.at)}</td><td>${e(q?.question||'Question')}</td><td>${e(cat?.name||'—')}</td><td><span class="badge ${a.correct?'approved':'rejected'}">${a.correct?'Correct':'Wrong'}</span></td><td>${q?link('practice/'+q.id,'Retry','link'):''}</td></tr>`}).join('')}</tbody></table></div>`:empty('No practice history yet','Your preparation history will appear here.')}`;
  }
  if(view==='notifications')body=`${heading('Notifications','Updates relevant to your account and preparation.')}${empty('No notifications','The current backend has no learner-notification model yet, so this page intentionally does not show fake alerts.')}`;
  if(view==='profile'||view==='settings')body=profileForm();
  return UI.layout(`<div class="container page learner-dashboard-shell"><div class="learner-mobile-head"><button class="btn ghost" type="button" data-action="learner-sidebar-toggle">${icon('menu')} Learning menu</button></div><div class="learner-shell">${side}<main class="learner-content"><div class="profile-band compact-profile-band">${avatar}<div><p class="eyebrow">YOUR LEARNING SPACE</p><h2>Welcome back, ${e(s?.name||'learner')}</h2><span class="small muted">Practice, review mistakes, follow job preparation, and track progress.</span></div></div>${body}</main></div></div>`) }
 function profileForm(){const s=MCQ.db.session;if(!s)return `<div class="card">${heading('Profile','Sign in to manage your profile.')} ${link('login','Log in','btn primary')}</div>`;const avatar=s.avatar?`<img class="profile-photo" src="${e(s.avatar)}" alt="Current profile photo">`:`<span class="profile-photo profile-photo-fallback">${e((s.name||'U').split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;return `<div class="profile-settings-grid"><div class="card"><h2>Edit profile</h2><div class="profile-photo-row">${avatar}<div><label class="btn sm" for="profile-image">Choose image</label><input class="visually-hidden" id="profile-image" type="file" accept="image/png,image/jpeg,image/webp"><p class="small muted">PNG, JPG or WebP. Maximum 600 KB.</p></div></div><form data-form="profile"><div class="form-grid">${field('name','Full name',s.name||'','text',true)}${field('email','Email',s.email||'','email',true)}${select('country','Country',[{id:'Pakistan',name:'Pakistan'},{id:'Other',name:'Other'}],s.country||'Pakistan',true)}</div><button class="btn primary">Save profile</button></form></div><div class="card"><h2>Change password</h2><p class="small muted">Enter your current password to choose a new one.</p><form data-form="password-change">${field('current_password','Current password','','password',true,'autocomplete="current-password"')}${field('new_password','New password','','password',true,'minlength="8" autocomplete="new-password"')}${field('confirm_password','Confirm new password','','password',true,'minlength="8" autocomplete="new-password"')}<button class="btn primary">Change password</button></form></div></div>`} function info(type){const d=MCQ.db;const titles={about:'About MCQ Campus',contact:'Contact Us',faq:'Frequently Asked Questions',privacy:'Privacy Policy',terms:'Terms & Conditions',disclaimer:'Disclaimer',cookies:'Cookie Policy',advertising:'Advertising Policy'};let body='';if(type==='about')body=`<p>MCQ Campus is an educational preparation platform designed to help students and job candidates practise multiple-choice questions, review past papers, strengthen weak areas, and stay informed about relevant examination and job opportunities.</p><p>Our aim is to make exam preparation more organised, practical, and accessible by bringing useful study resources into one focused platform.</p><h2>Our Mission</h2><p>Our mission is to help learners prepare more effectively through structured practice, useful learning resources, performance insights, and easy access to relevant educational content.</p><h2>What we provide</h2><ul><li>MCQ practice and important MCQs</li><li>Subject and category-based preparation</li><li>Past papers and competitive-exam preparation</li><li>Study guides and educational articles</li><li>Job and recruitment updates</li><li>Learner progress and saved-content tools where available</li></ul><h2>Accuracy and independence</h2><p>We aim to keep educational material useful and accurate, but information can contain errors or become outdated. Verify important examination, recruitment, eligibility, deadline, and official-announcement information with the relevant official authority.</p><p>MCQ Campus is an independent educational platform unless a specific official partnership is clearly stated.</p><h2>Have a suggestion, correction, or question?</h2>${link('contact','Visit Contact Us','btn primary')}`;
 if(type==='contact')body=`<p>${e(d.content.contact)}</p><form data-form="contact">${field('name','Name','','text',true)}${field('email','Email','','email',true)}${select('subject','Subject',[{id:'General Question',name:'General Question'},{id:'MCQ Correction',name:'MCQ Correction'},{id:'Technical Issue',name:'Technical Issue'},{id:'Job Information Correction',name:'Job Information Correction'},{id:'Advertising Inquiry',name:'Advertising Inquiry'},{id:'Privacy Question',name:'Privacy Question'},{id:'Other',name:'Other'}],'',true)}${textarea('message','Message','',true)}<button class="btn primary">Send message</button></form>`;
 if(type==='privacy')body='<p class="policy-updated">Last updated: September 21, 2026</p><p>MCQ Campus respects user privacy and aims to collect and use personal information responsibly.</p><h2>Information we may collect</h2><p>Depending on the features you use, this may include account details, optional profile information, saved content, MCQ attempts, scores, learning progress, preferences, device/browser information, and cookie or usage information.</p><h2>How information may be used</h2><p>Information may be used to create and authenticate accounts, save learning progress, provide supported personalised features, maintain security, detect abuse, understand website usage, and improve content and user experience.</p><h2>Analytics and advertising</h2><p>MCQ Campus may use analytics or advertising services where enabled. These services may use cookies or similar technologies subject to their own policies and applicable requirements. See the Cookie Policy and Advertising Policy for more information.</p><h2>Third-party links</h2><p>The website may link to official job websites, testing services, educational resources, advertisers, or other third parties. MCQ Campus does not control their privacy practices.</p><h2>Security and retention</h2><p>Reasonable technical and organisational measures may be used to protect information, but no system can promise absolute security. Information may be retained as necessary to provide services, maintain records, protect security, or meet applicable obligations.</p><h2>Your choices</h2><p>Depending on available features, users may update profile information, change passwords, manage saved content and preferences, or request account deletion.</p><h2>Children</h2><p>MCQ Campus does not knowingly request unnecessary sensitive personal data from children. Younger users should use the service with parent or guardian guidance where required.</p><h2>Changes and contact</h2><p>This policy may be updated as services, technologies, or legal requirements change. Use the Contact Us page for privacy-related questions.</p>';
 if(type==='terms')body='<p>By accessing or using MCQ Campus, users agree to these Terms & Conditions.</p><h2>Educational purpose</h2><p>MCQ Campus is intended primarily for educational, examination-preparation, informational, and learner-support purposes.</p><h2>User accounts</h2><p>Users are responsible for providing reasonable account information, keeping login credentials secure, and activities performed through their account.</p><h2>Acceptable use</h2><p>Users must not attempt unauthorised access, disrupt the website, upload malicious content, impersonate others, manipulate learner records, abuse reporting systems, or attempt to gain Admin or Super Admin access without authorisation.</p><h2>Educational and job information</h2><p>MCQs, explanations, guides, past-paper information, posts, and job information are provided for educational or informational purposes. Users should verify official advertisements, eligibility, fees, deadlines, schedules, documents and application instructions with the relevant authority.</p><h2>No guarantee</h2><p>MCQ Campus does not guarantee exam success, specific marks, job selection, interview selection, employment, admission, ranking, or financial outcomes.</p><h2>Intellectual property and third parties</h2><p>Original MCQ Campus branding, software, design, written material and educational content may be protected by applicable rights. Third-party names, logos and trademarks remain the property of their respective owners. External links are provided for convenience and are not controlled by MCQ Campus.</p><h2>Advertising and availability</h2><p>The website may display advertisements, sponsored content, or promotional material. Advertising does not automatically constitute endorsement. MCQ Campus may change, improve, temporarily suspend, or discontinue features where necessary.</p><h2>Accounts, changes and contact</h2><p>Accounts may be restricted for abuse, security violations, fraud, unauthorised access attempts, or serious violations of these terms. Terms may be updated from time to time. Use Contact Us for questions.</p>';
 if(type==='disclaimer')body='<p>MCQ Campus provides educational and informational resources intended to assist learners with preparation.</p><h2>Educational information</h2><p>MCQs, answers, explanations, guides, categories and past-paper material are provided for study purposes. Although efforts may be made to improve accuracy, content may contain errors, be incomplete, or become outdated.</p><h2>Job information</h2><p>Job and recruitment information may be collected, summarised, or referenced from public, official, or third-party sources. Users must verify details with the relevant official recruitment authority before applying.</p><h2>No guarantee of results</h2><p>Using MCQ Campus does not guarantee passing an exam, achieving specific marks, getting shortlisted, receiving admission, selection, or employment.</p><h2>Past papers and external links</h2><p>Past-paper content may be provided for educational reference and should not be interpreted as an official publication unless clearly stated. External websites are operated by third parties and remain responsible for their own content, security and policies.</p><h2>Affiliation</h2><p>Unless clearly stated otherwise, MCQ Campus is not officially affiliated with government departments, examination commissions, testing services, educational boards, or recruitment organisations referenced on the website.</p>';
 if(type==='faq')body='<div class="faq-list"><details open><summary>What is MCQ Campus?</summary><p>MCQ Campus is an educational preparation platform where learners can practise MCQs, review past papers, explore study material, track progress, and access relevant educational and job-related updates.</p></details><details><summary>Do I need an account?</summary><p>Some public content may be available without an account. Saved MCQs, preparation history, personalised progress, saved jobs, notifications and account preferences may require registration.</p></details><details><summary>Is MCQ Campus free?</summary><p>MCQ Campus may provide free educational content and services. If paid features are introduced, pricing and conditions should be displayed before purchase.</p></details><details><summary>Can MCQ answers contain mistakes?</summary><p>We aim to maintain accurate content, but errors can occur. Please report questionable questions or answers through the reporting or contact system.</p></details><details><summary>Are jobs listed on MCQ Campus official?</summary><p>Job information may be published or summarised from public or third-party sources. Always verify eligibility, deadlines, advertisements and application instructions with the official recruiting organisation.</p></details><details><summary>Does MCQ Campus guarantee selection or exam success?</summary><p>No. MCQ Campus provides preparation resources but cannot guarantee examination results, employment, selection, ranking or any other outcome.</p></details><details><summary>How can I contact MCQ Campus?</summary><p>Use the Contact Us page or officially configured contact details displayed on the website.</p></details></div>';
 if(type==='cookies')body='<p class="policy-updated">Last updated: September 21, 2026</p><p>Cookies are small pieces of information stored by websites or related services to support website functionality and preferences.</p><h2>Types of cookies we may use</h2><p><strong>Essential cookies</strong> may support authentication, account sessions, security, and core website functions. <strong>Preference cookies</strong> may remember theme or interface choices. <strong>Analytics cookies</strong> may be used when analytics services are enabled. <strong>Advertising cookies</strong> may be used by advertising providers when advertising is enabled.</p><h2>Local storage</h2><p>Browser local storage may also be used for interface preferences or website functionality.</p><h2>Third-party cookies</h2><p>Third-party analytics or advertising providers may set their own cookies subject to their policies and applicable consent requirements.</p><h2>Managing cookies</h2><p>You may manage or delete cookies through your browser settings. Disabling essential cookies may affect login or website functionality.</p><h2>Consent</h2><p>Where non-essential analytics or advertising cookies are enabled and consent is required, the website should apply a consent mechanism that actually controls those services.</p>';
 if(type==='advertising')body='<p>MCQ Campus may display advertising to help support the operation, maintenance and development of the platform.</p><h2>Types of advertising</h2><p>Advertising may include Google AdSense or other networks where enabled, direct brand advertisements, sponsored banners, sponsored educational promotions, recruitment-related promotions, or other clearly identified promotional content.</p><h2>Advertising vs educational content</h2><p>Advertising should be distinguishable from normal educational content. Sponsored placements should be labelled appropriately, and paid advertising should not be intentionally presented as independent educational content.</p><h2>Advertiser influence</h2><p>Advertisers do not automatically control MCQ answers, educational rankings, learner results, or independent educational content solely because they purchase advertising.</p><h2>Third-party and direct advertising</h2><p>Third-party advertising platforms may use cookies or browser information according to their own policies and applicable requirements. MCQ Campus may also accept direct brand advertising; acceptance does not automatically constitute endorsement.</p><h2>Restricted advertising</h2><p>MCQ Campus should not knowingly publish fraudulent, malicious, clearly misleading, illegal, malware-distributing, authority-impersonating, or intentionally deceptive advertising.</p><h2>Recruitment advertising and external sites</h2><p>Paid recruitment advertisements should be clearly distinguishable where necessary. Users should still verify opportunities and review third-party terms and privacy policies before providing information or making transactions.</p><h2>Advertising contact</h2><p>Use the Contact Us page and select Advertising Inquiry.</p>';
 return UI.layout(`<div class="container page">${crumbs([[titles[type]]])}<article class="article"><p class="eyebrow">MCQ CAMPUS</p><h1>${titles[type]}</h1>${body}</article></div>`)}
 function sitemap(){const groups=[['Main Pages',[['Home','home'],['MCQs','mcqs'],['Important MCQs','important'],['Categories','categories'],['Past Papers','papers'],['Jobs','jobs'],['Guides','guides'],['Blog','posts']]],['Account',[['Dashboard','dashboard'],['Profile','dashboard/profile'],['Settings','dashboard/settings']]],['Company / Support',[['About Us','about'],['Contact Us','contact'],['FAQ','faq']]],['Legal',[['Privacy Policy','privacy'],['Terms & Conditions','terms'],['Disclaimer','disclaimer'],['Cookie Policy','cookies'],['Advertising Policy','advertising']]]];return UI.layout(`<div class="container page">${crumbs([['Sitemap']])}${heading('Sitemap','Browse the main public sections of MCQ Campus.')}<div class="sitemap-grid">${groups.map(([g,items])=>`<div class="card"><h2>${g}</h2>${items.map(([l,p])=>link(p,l,'discovery-link')).join('')}</div>`).join('')}</div></div>`)}
 function notFound(){return UI.layout(`<div class="container page"><div class="error-page"><p class="eyebrow">404 · PAGE NOT FOUND</p><h1>We could not find that page.</h1><p>The link may be old, incomplete, or no longer available.</p><div class="actions">${link('home','Home','btn primary')}${link('search','Search','btn')}${link('categories','Categories','btn')}${link('papers','Past papers','btn')}</div></div></div>`)}
 return {home,quickCard,browse,listing,practice,mcq,relatedMcqs,questionCard,mini,guides,posts,auth,dashboard,info,profileForm,sitemap,notFound};
})();
